/* GEXFI H5 Income — interaction prototype. No production APIs or real funds. */
(()=>{'use strict';
const D=window.GXI_DATA, K='gexfi-income-h5-demo-v2', SCALE=1e6, DAY=86400000;
const products=[{days:90,rate:.038},{days:180,rate:.045},{days:365,rate:.05}];
const requestedLanguage=new URLSearchParams(location.search).get('lang');
let lang=['zh','en'].includes(requestedLanguage)?requestedLanguage:(localStorageSafe('get','gxi-lang')||'zh'), state, route='', amount=1000, chosen=180, range=30, holdingsFilter='all', activityFilter='all', consent={memo:false,risk:false}, quote=null, toastTimer, fundingMode='wallet', buyQuote=null, buyConsent=false, selectedPurchaseId=null;
function localStorageSafe(mode,key,value){try{if(mode==='get')return localStorage.getItem(key);localStorage.setItem(key,value)}catch(_){return null}}
const t=(zh,en)=>lang==='zh'?zh:en, esc=x=>String(x??'').replace(/[&<>"']/g,a=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[a]));
function num(v,d=2){return Number(v||0).toLocaleString(lang==='zh'?'zh-CN':'en-US',{minimumFractionDigits:d,maximumFractionDigits:d})}
const micro=v=>Math.round(Number(v)*SCALE), money=(m,d=2)=>num(Number(m||0)/SCALE,d), pBy=d=>products.find(p=>p.days===Number(d))||products[1];
const dayAdd=(date,n)=>new Date(Date.parse(date+'T00:00:00Z')+n*DAY).toISOString().slice(0,10);
const daysBetween=(a,b)=>Math.floor((Date.parse(b+'T00:00:00Z')-Date.parse(a+'T00:00:00Z'))/DAY);
function businessAdd(date,n){let d=date;while(n>0){d=dayAdd(d,1);if(![0,6].includes(new Date(d+'T00:00:00Z').getUTCDay()))n--;}return d}
function fmtdate(d){if(!d)return'—';return lang==='zh'?d.replaceAll('-',' / '):new Intl.DateTimeFormat('en',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T00:00:00Z'))}
const signedMoney=(n,d=2)=>(n>0?'+':'')+money(n,d);
const rate=d=>(pBy(d).rate*100).toFixed(2), calc=(principal,d,days=d)=>Math.round(principal*pBy(d).rate*days/365);
function seed(empty=false){const now='2026-10-09';return{schema:2,fiatOrders:[],demoRegion:'DEMO',now,verified:true,restriction:null,funds:{eligible:micro(empty?2500:9000),external:micro(3000),returned:0,reserved:0,pending:micro(500)},cardUSD:0,orders:[],cardOrders:[],positions:empty?[]:[{id:'IN-261009-001',days:180,principal:micro(2000),start:'2026-09-03',end:dayAdd('2026-09-03',180),status:'active',rate:.045,memo:'1.0',autoRenew:false},{id:'IN-261009-002',days:365,principal:micro(3000),start:'2026-07-09',end:dayAdd('2026-07-09',365),status:'active',rate:.05,memo:'1.0',autoRenew:false},{id:'IN-261009-003',days:90,principal:micro(1000),start:dayAdd(now,-90),end:now,status:'matured',rate:.038,memo:'1.0',autoRenew:false}],events:[],seq:100}}
function load(){try{let a=JSON.parse(localStorageSafe('get',K));return a?.schema===2?a:seed()}catch(_){return seed()}}
function save(){localStorageSafe('set',K,JSON.stringify(state))}
function id(prefix){state.seq++;return prefix+'-261009-'+state.seq}
function position(id){return state.positions.find(x=>x.id===id)}
function available(){return state.funds.eligible+state.funds.external+state.funds.returned}
function elapsed(p){return Math.min(p.days,Math.max(0,daysBetween(p.start,state.now)))}
function estimate(p){return Math.round(p.principal*p.rate*elapsed(p)/365)}
function holdTotal(){return state.positions.filter(p=>p.status!=='redeemed').reduce((n,p)=>n+p.principal,0)}
function estimateTotal(){return state.positions.filter(p=>p.status!=='redeemed').reduce((n,p)=>n+estimate(p),0)}
function paidTotal(){return state.positions.filter(p=>p.status==='redeemed').reduce((n,p)=>n+(p.actualIncome||0),0)}
function event(type,title,amt,ref){state.events.unshift({id:id('EV'),type,title,amount:amt,ref,date:state.now,at:new Date().toISOString()});save()}
const icons={back:'<path d="m14 5-7 7 7 7"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',exchange:'<path d="M4 8h16l-4-4M20 16H4l4 4"/>',card:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M3 10h18M7 15h4"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>',income:'<path d="M4 19V5m0 14h17M8 15l4-5 4 2 4-7"/>',wallet:'<path d="M20 8H5a2 2 0 0 1 0-4h13v4"/><rect x="3" y="8" width="18" height="12" rx="2"/><path d="M16 12h5v4h-5Z"/>',file:'<path d="M6 3h9l4 4v14H6Z"/><path d="M14 3v5h5M9 12h7M9 16h7"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 11 3 3 5-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 3"/>',check:'<path d="m5 12 4 4L20 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7M12 6v1"/>',support:'<path d="M4 13V11a8 8 0 0 1 16 0v6a4 4 0 0 1-4 4h-3"/><rect x="2" y="10" width="4" height="8" rx="2"/><rect x="18" y="10" width="4" height="8" rx="2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',chain:'<path d="m10 13 4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0" transform="translate(2 0) scale(.9)"/>',bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5ZM10 21h4"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12"/><circle cx="12" cy="12" r="3"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a18 18 0 0 0 0 18 18 18 0 0 0 0-18"/>'};
function I(name,size=19){return`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.file}</svg>`}
function btn(text,act='',kind='primary',attr=''){return`<button type="button" class="${kind}" ${act?`data-act="${act}"`:''} ${attr}>${text}</button>`}
function goBtn(text,to,kind='primary'){return btn(text,'',kind,`data-go="${to}"`)}
function link(text,to){return`<button type="button" class="link" data-go="${to}">${text}${I('chevron',13)}</button>`}
function def(label,value){return`<div class="definition"><dt>${label}</dt><dd>${value}</dd></div>`}
function notice(text,kind='',icon='info'){return`<div class="notice ${kind}">${I(icon,16)}<div>${text}</div></div>`}
function pill(label,kind=''){return`<span class="pill ${kind}">${label}</span>`}
function header(title='',back='products'){return`<header class="appbar"><div class="side">${btn(I('back'),'','icon-btn',`data-go="${back}" aria-label="${t('返回','Back')}"`)}</div><div class="title">${title}</div><div class="side end">${btn(lang==='zh'?'EN':'中','language','icon-btn lang',`aria-label="${t('切换英文','Switch to Chinese')}"`)}${btn(I('info',16),'demo','icon-btn',`aria-label="${t('演示控制','Demo controls')}"`)}</div></header>`}
function dock(label,act,attr='',caption=''){return`<div class="dock">${caption?`<div class="caption">${caption}</div>`:''}${btn(label,act,'primary',attr)}</div>`}
function productLine(days){return`<div class="row start"><span class="tether small">₮</span><div><h3>USDT Income ${days}</h3><div class="caption">${days}${t('天',' days')} · ${t('目标年化','Net target p.a.')} ${rate(days)}%</div></div></div>`}
function statusLabel(s){return ({active:t('持有中','Active'),matured:t('待到期结算','Matured'),redeeming:t('结算处理中','Settling'),redeem_failed:t('结算待处理','Action needed'),redeemed:t('已入账钱包','Credited'),pending:t('待受理','Pending acceptance'),accepted:t('已受理','Accepted'),cancelled:t('已取消','Cancelled'),rejected:t('未受理','Not accepted'),processing:t('处理中','Processing'),completed:t('已完成','Completed'),failed:t('未完成','Failed')})[s]||s}
function demoStrip(){return`<div class="demo-strip"><span>${t('交互演示 · 不连接真实资金','Interactive demo · no real funds')}</span><button data-act="demo">${t('场景切换','Scenarios')}</button></div>`}
function routeId(){return route.split('/')[1]}
function navOriginal(active){return`<nav class="original-nav">${[['home','home',t('首页','Home')],['exchange','exchange',t('汇兑','Exchange')],['card','card',t('银联卡','UnionPay')],['me','user',t('我的','Me')]].map(([r,i,l])=>btn(I(i)+l,'',''+(active===r?'active':''),`data-go="${r==='card'?'bridge/card':r}"`)).join('')}</nav>`}
function sourceImg(n){return`<img class="source-strip" src="${D.images[n]}" alt="${t('用户提供的现有H5截图：','Existing H5 screenshot supplied by user: ')+n}">`}
function entry(home=true){return`<button class="entry-card ${home?'':'dark'}" data-go="${home?'products':'holdings'}"><div class="entry-title"><span class="tether small">₮</span>${t('USDT 收益宝','GEX USDT Income')}<span class="new-marker">${t('新增入口','NEW ENTRY')}</span></div><div class="entry-desc">${home?t('以 USDT 申购，按所选固定期限持有。','Subscribe in USDT for a defined term.'):t('持仓与钱包余额分别记录。','Income holdings are separate from available wallet funds.')}</div>${home?`<div class="entry-rates">${products.map(p=>`<div><span>${p.days}${t('天',' days')}</span><strong>${rate(p.days)}<small>%</small></strong></div>`).join('')}</div>`:`<div class="entry-rates"><div style="grid-column:span 2"><span>${t('持仓本金 · 演示','Holding principal · demo')}</span><strong>${money(holdTotal())}<small> USDT</small></strong></div></div>`}<div class="entry-link"><span>${home?t('扣管理费后目标年化 · 非保证收益','Net target p.a. · not guaranteed'):t('查看持仓与到期进度','View holdings & maturity')}</span>${I('arrow',16)}</div></button>`}
function moreArea(){return `<div class="more-wrap">${sourceImg('more')}<button class="more-slot" data-go="products"><span>${I('income',23)}</span>${t('收益中心','Income')}</button></div>`}
function originalPage(type){let body='';if(type==='home')body=sourceImg('home-top')+entry()+sourceImg('home-bottom');else if(type==='exchange')body=sourceImg('exchange');else if(type==='more')body=moreArea();else body=sourceImg('me-top')+entry(false)+sourceImg('me-middle')+sourceImg('me-wallet')+moreArea();
return`<div class="original-page ${type==='home'?'':'me'}"><div class="source-label">${t('原页截图定位 · 仅新增收益宝入口','Original-page reference · Income entry added only')}</div>${body}</div>${navOriginal(type==='more'?'me':type)}`}
function termCard(p){return`<button class="term-card" data-go="product/${p.days}"><div class="term-head"><span class="term-title">${p.days} ${t('天定期','days')}</span>${I('chevron',17)}</div><div class="term-rate"><span class="rate">${rate(p.days)}<small>%</small></span><span class="caption">${t('扣管理费后\n目标年化','Net target p.a.').replace('\n','<br>')}</span></div><div class="term-foot"><span>${t('每 1,000 USDT 持满期限预计收益','Illustrative income per 1,000 USDT')}</span><b>+${money(calc(micro(1000),p.days))}</b></div></button>`}
function productsPage(){const pending=state.orders.filter(o=>o.status==='pending').length,matured=state.positions.filter(p=>p.status==='matured'||p.status==='redeem_failed').length;return header(t('USDT 收益宝','GEX USDT Income'),'home')+`<main class="page"><div class="eyebrow">GEXFI · INCOME</div><h1>${t('让每一段持有，\n都有清晰计划。','A clear plan for\nevery holding.').replace('\n','<br>')}</h1><p class="subtle">${t('选择固定期限，查看收益记录。到期结算后回到 GEXFI 钱包。','Choose a defined term, track income records and settle back to GEXFI Wallet at maturity.')}</p><div class="card mt"><div class="row"><span class="caption">${t('我的收益资产','My Income holdings')}</span>${link(t('查看持仓','View holdings'),'holdings')}</div><div class="large-number" style="font-size:29px;margin-top:11px">${money(holdTotal())}<small>USDT</small></div><div class="stat-pair"><div><span>${t('预计累计收益','Estimated accrued income')}</span><strong class="green">+${money(estimateTotal())}</strong></div><div><span>${t('已结算收益','Settled income')}</span><strong>${money(paidTotal())}</strong></div></div></div>${pending||matured?`<div class="spacer-sm"></div>${notice(`${pending?t(`${pending} 笔申购待受理。`,`${pending} subscription(s) pending. `):''}${matured?t(`${matured} 笔持仓可查看到期结算。`,`${matured} holding(s) ready for maturity review.`):''} ${link(t('查看','View'),'holdings')}`)}`:''}<div class="section-line"><h2>${t('选择持有期限','Choose your term')}</h2>${link(t('申购资格','Eligibility'),'eligibility')}</div>${products.map(termCard).join('')}<div class="spacer"></div>${notice(t('首期仅接受通过 GEXFI 购买并已完成入账的合资格 USDT；外部转入资金暂不支持申购。','Initially available only for eligible, settled USDT purchased through GEXFI. Direct external deposits are not eligible.'))}<div class="card mt tight"><button class="list-item" data-go="memo"><div class="row start"><span class="list-icon">${I('file')}</span><div><span class="list-title">${t('投资说明书','Investment Memorandum')}</span><p>${t('版本 1.0 · 中英文在线阅读与 PDF','Version 1.0 · EN / 中文 · online & PDF')}</p></div></div>${I('chevron',15)}</button><button class="list-item" data-go="rules"><div><span class="list-title">${t('产品规则与风险','Product rules & risks')}</span><p>${t('固定期限、单利计算、到期结算','Fixed term · simple interest · maturity settlement')}</p></div>${I('chevron',15)}</button></div><div class="footnote">${t('目标收益不保证，本金存在风险。预计收益不等于已确认或已入账金额。','Target returns are not guaranteed. Capital is at risk. Estimates are neither confirmed income nor credited funds.')}</div></main>`}
function trialRows(days,a){const total=calc(micro(a),days);return def(t('预计持满期限收益','Illustrative full-term income'),`<strong class="green">+${money(total)} USDT</strong>`)+def(t('预计每日收益','Illustrative daily accrual'),`${money(calc(micro(a),days,1),6)} USDT`)+def(t('本金与预计收益合计','Principal + illustrative income'),`${money(micro(a)+total)} USDT`)}
function productPage(days){chosen=Number(days);const p=pBy(days);return header(t('产品详情','Product details'),'products')+`<main class="page has-dock"><section class="detail-hero"><div class="row"><div class="row start"><span class="tether">₮</span><div><div class="detail-title">GEX USDT Income</div><div class="caption">${days} ${t('天固定期限','day fixed term')}</div></div></div>${pill(t('USDT 计价','USDT'))}</div><div class="rate">${rate(days)}<small>%</small></div><div class="subtle">${t('扣除产品管理费后的目标年化收益率','Net target annualized rate after product management fee')}</div><div class="facts"><div><span>${t('持有期限','Term')}</span><b>${days} ${t('个自然日','calendar days')}</b></div><div><span>${t('赎回方式','Redemption')}</span><b>${t('到期结算至钱包','Wallet settlement at maturity')}</b></div><div><span>${t('收益计算','Calculation')}</span><b>${t('ACT/365 · 单利','ACT/365 · simple interest')}</b></div><div><span>${t('自动续投','Auto-renewal')}</span><b>${t('默认不续投','Off by default')}</b></div></div></section><div class="tabs">${products.map(q=>btn(q.days+t('天',' days'),'',''+(q.days===Number(days)?'active':''),`data-go="product/${q.days}"`)).join('')}</div><div class="card"><div class="row"><h3>${t('收益试算','Income illustration')}</h3><span class="caption">USDT</span></div><div class="amount-wrap"><input id="trial-amount" inputmode="decimal" type="number" min="0" max="50000" value="${amount}" aria-label="${t('试算金额','Illustration amount')}"><span>USDT</span></div><div class="chips">${[100,1000,5000].map(x=>btn(num(x,0),'trial','','data-value="'+x+'"')).join('')}</div><div class="spacer-sm"></div><div id="trial-rows">${trialRows(days,amount)}</div><div class="caption">${t('试算按目标收益率计算，不代表保证回报；每日计提不等于每日派付。','Illustrations use the target rate and are not guaranteed returns. Daily accrual is not a daily payout.')}</div></div><div class="card mt tight">${def(t('产品管理费','Management fee'),t('年化 0.50%，已反映于展示收益','0.50% p.a.; reflected in shown target'))}${def(t('常规提前赎回','Ordinary early redemption'),t('不支持','Not available'))}${def(t('到账时间','Settlement timing'),t('确认前展示订单适用时效','Order-specific timing shown before confirmation'))}<button class="list-item" data-go="memo"><span>${t('阅读 Investment Memorandum','Read Investment Memorandum')}</span>${I('chevron',15)}</button></div><div class="spacer"></div>${notice(t('展示收益不会再重复扣除 0.50% 产品管理费。兑换、转账及卡充值属于另行选择的独立服务。','The 0.50% management fee is not deducted again from the displayed net target. FX, transfers and card funding are separate optional services.'))}<p class="footnote">${t('目标收益不保证，本金存在风险。','Target returns are not guaranteed. Capital is at risk.')}</p></main>`+dock(t('申购此产品','Subscribe'),'start-subscribe',`data-days="${days}"`)}
function eligibilityPage(){const f=state.funds;return header(t('申购资格与资金','Eligibility & funds'),'products')+`<main class="page"><div class="card"><div class="row"><h3>${t('账户资格','Account eligibility')}</h3>${pill(state.verified?t('已验证 · 演示','Verified · demo'):t('需完成认证','Verification required'),state.verified?'green':'amber')}</div><p class="subtle">${state.verified?t('账户已通过本地演示资格检查。真实申购以服务端校验结果为准。','This demo account passes eligibility checks. Actual subscriptions require server-side approval.'):t('完成账户认证后，再查看可申购产品。','Complete account verification before subscribing.')}</p>${!state.verified?goBtn(t('前往现有认证中心','Open existing verification centre'),'bridge/kyc','secondary'):''}</div><div class="section-line"><h2>${t('USDT 资金构成','USDT funding breakdown')}</h2></div><div class="card"><span class="caption">${t('可申购金额','Eligible available amount')}</span><div class="large-number" style="margin:9px 0 20px">${money(f.eligible)}<small>USDT</small></div>${def(t('已结算的 GEXFI 购U资金','Settled eligible GEXFI purchases'),`${money(f.eligible)} USDT`)}${def(t('其他订单已占用','Reserved for pending orders'),`${money(f.reserved)} USDT`)}${def(t('待入账购U资金','Pending purchase settlement'),`${money(f.pending)} USDT`)}${def(t('外部转入（不可申购）','External deposits (not eligible)'),`${money(f.external)} USDT`)}${def(t('赎回款（需重新核验资格）','Redemption proceeds (recheck eligibility)'),`${money(f.returned)} USDT`)}</div><div class="spacer"></div>${notice(t('钱包总余额不等于收益宝可申购金额。待入账或已占用金额不可重复使用。','Wallet balance is not the same as eligible Income funds. Unsettled or reserved balances cannot be reused.'))}<div class="card mt tight"><button class="list-item" data-go="buy/180"><div><span class="list-title">${t('通过 GEXFI 购买 USDT','Buy USDT through GEXFI')}</span><p>${t('沿用现有汇兑与入账流程','Uses the existing exchange and settlement flow')}</p></div>${I('arrow',17)}</button><button class="list-item" data-go="activity"><span>${t('查看收益模块资金记录','View Income activity')}</span>${I('chevron',15)}</button></div><div class="spacer"></div>${goBtn(t('返回选择产品','Back to products'),'products')}</main>`}
function amountError(v){if(!state.verified)return t('请先完成账户认证。','Complete account verification first.');if(state.restriction)return t('账户暂不接受新申购，请联系客户服务。','New subscriptions are unavailable for this account.');if(!Number.isFinite(Number(v))||!v||v<100)return t('本演示最低申购金额为 100 USDT。','This demo uses a 100 USDT minimum.');if(v>50000)return t('本演示单笔上限为 50,000 USDT。','This demo uses a 50,000 USDT per-order limit.');if(micro(v)>state.funds.eligible)return t('可申购金额不足；外部转入与待入账资金不计入。','Insufficient eligible funds; external and unsettled funds are excluded.');if(!/^\d+(\.\d{1,6})?$/.test(String(v)))return t('金额最多支持 6 位小数。','Use no more than six decimal places.');return''}
function subscribePage(days){chosen=Number(days);const e=amountError(amount);return header(t('申购收益宝','Subscribe'),'product/'+days)+`<main class="page has-dock"><div class="card tight">${productLine(days)}</div><div class="card mt"><div class="row"><label class="input-label" for="subscribe-amount">${t('申购金额','Subscription amount')}</label>${link(t('资金明细','Funding details'),'eligibility')}</div><div class="amount-wrap"><input id="subscribe-amount" inputmode="decimal" type="number" min="100" max="50000" step="0.000001" value="${amount}" aria-label="${t('申购金额','Subscription amount')}"><span>USDT</span></div><div class="caption">${t('可申购余额','Eligible available')} ${money(state.funds.eligible)} USDT</div><div class="chips">${[100,500,1000].map(x=>btn(num(x,0),'amount','','data-value="'+x+'"')).join('')}${btn(t('全部','Max'),'amount','','data-value="max"')}</div><div class="input-error" id="amount-error">${e}</div></div><div class="card mt"><h3>${t('预计收益','Income illustration')}</h3><div id="subscription-rows">${trialRows(days,amount)}</div><div class="caption">${t('预计金额不保证。目标年化已反映管理费，不重复扣除。','Estimates are not guaranteed. The net target already reflects the management fee.')}</div></div><div class="spacer"></div>${notice(t('确认后先占用申购金额。收到受理确认后开始持有；未受理或受理前成功取消，金额退回可用余额。','Funds are reserved on submission. The term starts only after acceptance. A rejected or successfully cancelled instruction releases the reservation.'))}<p class="footnote">${t('演示限额：100–50,000 USDT。实际限额、起息与到期时间由订单接口提供，不是本次新增合同条款。','Demo limits: 100–50,000 USDT. Actual limits and term timestamps must be supplied by the order service.')}</p></main>`+dock(t('下一步，核对申购','Review subscription'),'review','id="review-button" '+(e?'disabled':''))}
function reviewPage(){return header(t('核对申购','Review subscription'),'subscribe/'+chosen)+`<main class="page has-dock"><div class="card"><span class="caption">${t('申购金额','Subscription amount')}</span><div class="large-number" style="margin:10px 0 20px">${num(amount)}<small>USDT</small></div>${productLine(chosen)}<div class="spacer"></div>${def(t('目标年化（扣管理费后）','Net target p.a.'),rate(chosen)+'%')}${def(t('预计收益','Illustrative income'),`<span class="green">+${money(calc(micro(amount),chosen))} USDT</span>`)}${def(t('拟起息日期 · 演示','Illustrative start'),fmtdate(state.now))}${def(t('拟到期日期 · 演示','Illustrative maturity'),fmtdate(dayAdd(state.now,chosen)))}${def(t('结算预计完成 · 演示','Illustrative settlement by'),fmtdate(businessAdd(dayAdd(state.now,chosen),2)))}${def(t('到期资金去向','Maturity destination'),'GEXFI Wallet')}${def(t('自动续投','Auto-renewal'),t('关闭','Off'))}${def(t('投资说明书','Memorandum'),'v1.0 · 2026-10-08')}</div><div class="card mt tight"><button class="list-item" data-go="memo"><div><span class="list-title">${t('阅读投资说明书','Read Investment Memorandum')}</span><p>${t('期限、费用、资金持有安排与风险','Terms, fees, asset-holding arrangements & risks')}</p></div>${I('file',17)}</button><button class="list-item" data-go="rules"><span>${t('申购确认条款与风险摘要','Subscription terms & risk summary')}</span>${I('chevron',15)}</button></div><label class="check-row"><input type="checkbox" id="consent-memo" ${consent.memo?'checked':''}><span>${t('我已阅读 Investment Memorandum 及本页显示的申购条件。','I have read the Investment Memorandum and the subscription conditions shown here.')}</span></label><label class="check-row"><input type="checkbox" id="consent-risk" ${consent.risk?'checked':''}><span>${t('我理解该产品为固定期限，目标收益不保证，本金存在风险，不提供常规提前赎回。','I understand the fixed term, the non-guaranteed target and capital risk, and that ordinary early redemption is unavailable.')}</span></label>${notice(t('本按钮仅演示提交状态，不签订真实合同。正式接入时须由服务端提供该账户适用的申购协议及结算条款。','This button simulates submission only; it does not sign a contract. Production must provide account-specific agreements and settlement terms.'))}</main>`+dock(t('确认模拟申购','Confirm demo subscription'),'submit','id="confirm-subscribe" '+(!(consent.memo&&consent.risk)?'disabled':''))}
function orderPage(orderId){const o=state.orders.find(o=>o.id===orderId);if(!o)return productsPage();const pending=o.status==='pending';return header(t('申购记录','Subscription record'),'holdings')+`<main class="page"><div class="result-hero"><div class="result-icon ${pending?'pending':o.status==='accepted'?'':'failed'}">${I(pending?'clock':o.status==='accepted'?'check':'info',27)}</div><h1>${statusLabel(o.status)}</h1><p class="subtle">${pending?t('金额已预留，等待受理确认。','Funds reserved. Awaiting acceptance.'):o.status==='accepted'?t('已建立持仓，按受理确认开始计算持有期。','Your holding has been created under its acceptance terms.'):t('本次指令未建立持仓，预留金额已释放。','No holding was created. The reservation has been released.')}</p><div class="large-number">${money(o.principal)}<small>USDT</small></div></div><div class="card">${def(t('订单编号','Order ID'),o.id)}${def(t('产品','Product'),`USDT Income ${o.days}`)}${def(t('目标年化','Net target p.a.'),rate(o.days)+'%')}${def(t('提交日期','Submitted'),fmtdate(o.created))}${def(t('资金状态','Funds status'),pending?t('预留中，不可重复使用','Reserved; unavailable elsewhere'):o.status==='accepted'?t('已计入收益持仓','Included in Income holdings'):t('已释放至可用余额','Released to available funds'))}</div><div class="spacer"></div>${pending?`${notice(t('等待服务端受理。可通过右上角演示控制模拟“受理”“拒绝”；生产页面不显示这些控制。','Waiting for server acceptance. Demo controls can simulate acceptance or rejection; these controls do not appear in production.'))}<div class="spacer"></div>${btn(t('取消未受理申购','Cancel pending subscription'),'cancel-order','secondary',`data-id="${o.id}"`)}`:o.status==='accepted'?goBtn(t('查看持仓','View holding'),'holding/'+o.positionId):goBtn(t('返回产品','Back to products'),'products')}<div class="spacer-sm"></div>${goBtn(t('查看全部记录','View all activity'),'activity','secondary')}</main>`}
function holdingCard(p){return`<button class="term-card" data-go="holding/${p.id}"><div class="row">${productLine(p.days)}${pill(statusLabel(p.status),p.status==='active'?'':p.status==='redeemed'?'green':'amber')}</div><div class="row" style="margin:17px 0 8px"><div><span class="caption">${t('持仓本金','Principal')}</span><div style="font-size:24px;letter-spacing:-.5px;margin-top:5px">${money(p.principal)} <small style="font-size:10px">USDT</small></div></div>${I('chevron',16)}</div><div class="term-foot"><span>${fmtdate(p.end)} ${t('到期','maturity')}</span><b class="green">${p.status==='redeemed'?t('实际收益 ','Actual income '):t('预计收益 ','Estimated ')}${signedMoney(p.status==='redeemed'?p.actualIncome:estimate(p))}</b></div></button>`}
function holdingsPage(){const filtered=state.positions.filter(p=>holdingsFilter==='all'||(holdingsFilter==='active'?p.status==='active':holdingsFilter==='matured'?['matured','redeeming','redeem_failed'].includes(p.status):p.status==='redeemed'));return header(t('我的收益资产','My Income holdings'),'products')+`<main class="page"><div class="card"><div class="row"><span class="caption">${t('持仓本金','Holding principal')}</span>${pill('USDT')}</div><div class="large-number" style="margin-top:10px">${money(holdTotal())}</div><div class="stat-pair"><div><span>${t('累计预计收益','Estimated accrued income')}</span><strong class="green">+${money(estimateTotal())}</strong></div><div><span>${t('累计已结算收益','Total settled income')}</span><strong>${money(paidTotal())}</strong></div></div><div class="spacer"></div>${link(t('查看资金与收益记录','View activity & income'),'activity')}</div><div class="section-line"><h2>${t('持仓明细','Your holdings')}</h2>${link(t('继续申购','Subscribe'),'products')}</div><div class="tab-filters">${[['all',t('全部','All')],['active',t('持有中','Active')],['matured',t('到期 / 结算','Maturity')],['redeemed',t('已赎回','Redeemed')]].map(([v,l])=>btn(l,'hold-filter',v===holdingsFilter?'active':'',`data-value="${v}"`)).join('')}</div>${state.orders.filter(o=>o.status==='pending').map(o=>`<div class="card tight"><button class="list-item" data-go="order/${o.id}"><div><span class="list-title">${t('申购待受理','Subscription pending')}</span><p>USDT Income ${o.days} · ${money(o.principal)} USDT</p></div>${I('clock',18)}</button></div><div class="spacer-sm"></div>`).join('')}${filtered.length?filtered.map(holdingCard).join(''):`<div class="card empty">${I('income',33)}<h3>${t('暂无该类持仓','No holdings in this category')}</h3><p>${t('选择合适的固定期限，完成首次申购。','Choose a defined term to start your first subscription.')}</p>${goBtn(t('查看产品','Explore products'),'products','secondary')}</div>`}<p class="footnote">${t('持仓本金与预留金额不属于钱包可用余额；预计收益尚未入账，不计入可消费资金。','Holding principal and reserved funds are not available wallet cash. Estimated income is not credited or spendable.')}</p></main>`}
function chart(p){const n=Math.min(range||p.days,Math.max(1,elapsed(p))), first=Math.max(0,elapsed(p)-n), max=Math.max(1,estimate(p)/SCALE), pts=[];for(let i=0;i<=12;i++){const days=first+n*i/12;pts.push([8+i*25,129-((p.principal/SCALE*p.rate*days/365)/max)*106])}return`<svg class="graph" viewBox="0 0 320 150" role="img" aria-label="${t('按目标收益率计算的预计累计收益线，非历史业绩','Illustrative cumulative target accrual, not historical performance')}"><path d="M8 25H309M8 77H309M8 129H309" stroke="#e7edf2"/><path d="M${pts.map(p=>p.join(',')).join('L')}L308,129L8,129Z" fill="#eaf0f6"/><path d="M${pts.map(p=>p.join(',')).join('L')}" stroke="#6488aa" stroke-width="2" fill="none"/><circle cx="308" cy="${pts[pts.length-1][1]}" r="3" fill="#456e95"/><text x="8" y="146">${dayAdd(p.start,first).slice(5)}</text><text x="276" y="146">${dayAdd(p.start,elapsed(p)).slice(5)}</text></svg>`}
function holdingPage(pid){const p=position(pid);if(!p)return holdingsPage();return header(t('持仓详情','Holding details'),'holdings')+`<main class="page"><div class="card"><div class="row">${productLine(p.days)}${pill(statusLabel(p.status),p.status==='active'?'':'amber')}</div><div class="label" style="margin-top:21px">${t('持仓本金','Principal')}</div><div class="large-number">${money(p.principal)}<small>USDT</small></div><div class="stat-pair"><div><span>${p.status==='redeemed'?t('实际结算收益','Actual settled income'):t('累计预计收益','Estimated accrued income')}</span><strong class="${p.status==='redeemed'&&p.actualIncome<0?'danger':'green'}">${signedMoney(p.status==='redeemed'?p.actualIncome:estimate(p))}</strong></div><div><span>${t('预计每日收益','Illustrative daily accrual')}</span><strong style="font-size:17px">${money(Math.round(p.principal*p.rate/365),6)}</strong></div></div><div class="progress"><span style="width:${Math.min(100,elapsed(p)/p.days*100)}%"></span></div><div class="row caption"><span>${fmtdate(p.start)}</span><span>${t('已持有','Held')} ${elapsed(p)} / ${p.days} ${t('天','days')}</span></div></div><div class="card mt">${def(t('到期日','Maturity'),fmtdate(p.end))}${def(t('目标年化（扣管理费后）','Net target p.a.'),(p.rate*100).toFixed(2)+'%')}${def(t('实际收益确认','Actual income confirmation'),p.status==='redeemed'?money(p.actualIncome)+' USDT':t('结算时确认','Confirmed at settlement'))}${def(t('到期安排','Maturity instruction'),t('结算回钱包，不自动续投','Settle to wallet; no auto-renewal'))}<div class="spacer-sm"></div>${p.status==='active'?goBtn(t('查看到期安排','Maturity instructions'),'maturity/'+p.id,'secondary'):p.status==='matured'?goBtn(t('申请到期结算','Request maturity settlement'),'redeem/'+p.id):['redeeming','redeem_failed'].includes(p.status)?goBtn(t('查看结算进度','Track settlement'),'settlement/'+p.id):goBtn(t('查看钱包入账','View wallet credit'),'settlement/'+p.id)}</div><div class="section-line"><h2>${t('预计收益趋势','Illustrative accrual')}</h2>${link(t('每日明细','Daily records'),'income/'+p.id)}</div><div class="card"><div class="tabs compact">${[7,30,90,0].map(r=>btn(r?r+t('天','d'):t('全部','All'),'range',range===r?'active':'',`data-value="${r}"`)).join('')}</div>${chart(p)}<div class="caption">${t('依据目标年化计算的示意计提线，不是实际投资业绩或已支付收益。','Calculated using the target rate; not actual investment performance or paid income.')}</div></div><div class="card mt tight"><button class="list-item" data-go="receipt/${p.id}"><div class="row start">${I('file',18)}<span>${t('申购确认与数字凭证','Confirmation & digital record')}</span></div>${I('chevron',14)}</button><button class="list-item" data-go="chain/${p.id}"><div class="row start">${I('chain',18)}<span>${t('链上记录状态','On-chain record status')}</span></div>${I('chevron',14)}</button><button class="list-item" data-go="early/${p.id}"><span>${t('提前退出规则','Early-exit rules')}</span>${I('chevron',14)}</button><button class="list-item" data-go="activity"><span>${t('资金活动记录','Account activity')}</span>${I('chevron',14)}</button></div></main>`}
function dailyPage(pid){const p=position(pid);if(!p)return holdingsPage();let n=Math.min(range||365,elapsed(p));let entries=[];for(let i=0;i<n;i++){const d=elapsed(p)-i;entries.push(`<div class="list-item"><div><span class="list-title">${fmtdate(dayAdd(p.start,d))}</span><p>${t('预计计提 · 未派付','Estimated accrual · not paid')}</p></div><div class="right"><strong class="green">+${money(Math.round(p.principal*p.rate/365),6)}</strong><small>USDT</small></div></div>`)}return header(t('每日收益明细','Daily income records'),'holding/'+p.id)+`<main class="page"><div class="card"><div class="row"><span class="caption">${t('累计预计收益','Estimated accrued income')}</span>${link(t('导出','Export'),'export/'+p.id)}</div><div class="large-number green" style="margin:10px 0">+${money(estimate(p))}<small>USDT</small></div>${def(t('已确认收益','Confirmed income'),p.status==='redeemed'?money(p.actualIncome):t('结算时确认','At settlement'))}${def(t('已入账收益','Credited income'),p.status==='redeemed'?money(p.actualIncome):'0.00')}</div><div class="tabs">${[7,30,90,0].map(r=>btn(r?r+t('天','d'):t('全部','All'),'range',range===r?'active':'',`data-value="${r}"`)).join('')}</div><div class="card tight">${entries.join('')||`<div class="empty">${t('尚未开始计提','Accrual has not started')}</div>`}</div></main>`}
function receiptPage(pid){const p=position(pid);if(!p)return holdingsPage();return header(t('申购确认','Subscription confirmation'),'holding/'+p.id)+`<main class="page"><div class="badge-line"><span class="eyebrow" style="margin:0">GEXFI / INCOME</span>${pill(t('演示记录','Demo record'))}</div><div class="card">${productLine(p.days)}<div class="spacer"></div>${def(t('确认编号','Confirmation ID'),p.id)}${def(t('申购本金','Principal'),money(p.principal)+' USDT')}${def(t('产品期限','Term'),p.days+t(' 个自然日',' calendar days'))}${def(t('目标年化','Net target p.a.'),(p.rate*100).toFixed(2)+'%')}${def(t('管理费口径','Management fee'),t('已反映，不重复扣除','Reflected; not charged again'))}${def(t('起息日期','Start date'),fmtdate(p.start))}${def(t('到期日期','Maturity'),fmtdate(p.end))}${def(t('计息规则','Day count'),'ACT/365 · '+t('单利','simple interest'))}${def(t('资金来源','Funding source'),t('已结算合资格 GEXFI 购U资金','Settled eligible GEXFI-purchased USDT'))}${def(t('说明书版本','Memorandum version'),'1.0 · 2026-10-08')}${def(t('续投指令','Renewal mandate'),t('未授权','Not authorized'))}${def(t('链上凭证','On-chain record'),t('未生成','Not issued'))}</div><div class="spacer"></div>${notice(t('本地演示确认单不构成真实受理或法律合同。生产确认单须记录实际签约主体、申购协议版本、受理时间与服务端签名。','A local demo record is not an accepted contract. Production confirmations must retain the actual counterparty, agreement version, acceptance timestamp and server reference.'))}<div class="button-pair">${btn(t('下载确认记录','Download record'),'download-receipt','secondary',`data-id="${p.id}"`)}${goBtn(t('查看说明书','Memorandum'),'memo','secondary')}</div></main>`}
function chainPage(pid){const p=position(pid);return header(t('链上记录','On-chain records'),p?'holding/'+p.id:'holdings')+`<main class="page"><div class="card empty">${I('chain',35)}<h3>${t('尚无可验证的链上记录','No verifiable on-chain record')}</h3><p>${t('当前显示的是收益账户内的申购记录，\n并非已发行的链上 Token。','The current confirmation is an account record,\nnot an issued on-chain token.').replace('\n','<br>')}</p>${pill(t('未生成 · 不显示模拟哈希','Not issued · no mock transaction hash'))}</div><div class="card mt">${def(t('对应持仓','Holding'),p?.id||'—')}${def(t('网络','Network'),'—')}${def(t('交易哈希','Transaction hash'),'—')}${def(t('链上确认状态','Confirmation status'),t('无真实交易记录','No actual transaction'))}</div><div class="spacer"></div>${notice(t('仅在真实网络、交易哈希及确认状态均可验证时开放浏览器验证入口。内部凭证不证明底层资产所有权、保本或自由转让权。','An explorer link is enabled only for an actual network, transaction hash and confirmation status. An internal record does not establish asset ownership, capital protection or transferability.'))}</main>`}
function maturityPage(pid){const p=position(pid);if(!p)return holdingsPage();return header(t('到期安排','Maturity instructions'),'holding/'+p.id)+`<main class="page"><div class="card">${productLine(p.days)}<div class="spacer"></div>${def(t('到期日','Maturity'),fmtdate(p.end))}${def(t('剩余天数','Days remaining'),Math.max(0,daysBetween(state.now,p.end))+t(' 天',' days'))}${def(t('到期本金','Principal at maturity'),money(p.principal)+' USDT')}${def(t('预计持满期限收益','Illustrative full-term income'),money(calc(p.principal,p.days))+' USDT')}</div><div class="section-line"><h2>${t('当前安排','Current instruction')}</h2></div><div class="card"><div class="row"><span class="list-icon">${I('wallet')}</span><div style="flex:1"><h3>${t('到期结算至 GEXFI 钱包','Settle to GEXFI Wallet')}</h3><div class="caption">${t('不自动转卡，不默认续投','No automatic card funding or renewal')}</div></div>${I('check',18)}</div></div><div class="card mt"><h3>${t('需要再次申购？','Planning to reinvest?')}</h3><p class="subtle">${t('结算入账后，重新核验资金资格并选择当时可用产品。新订单重新确认利率、期限与文件版本。','After settlement, eligibility is checked again and a new product is selected. A new order confirms the rate, term and document version.')}</p>${link(t('浏览当前产品','Browse current products'),'products')}</div><div class="spacer"></div>${notice(t('到期日并不等于即时可用。预计结算日期及处理状态随订单显示；本演示使用到期后 2 个工作日作为流程样例。','Maturity is not instant availability. Timing is retained with each order. This demo illustrates two business days after maturity.'))}<div class="spacer"></div>${p.status==='matured'?goBtn(t('申请到期结算','Request maturity settlement'),'redeem/'+p.id):goBtn(t('返回持仓','Back to holding'),'holding/'+p.id,'secondary')}</main>`}
function earlyPage(pid){const p=position(pid);return header(t('提前退出规则','Early-exit rules'),p?'holding/'+p.id:'rules')+`<main class="page"><div class="card"><div class="row start"><span class="list-icon">${I('lock',22)}</span><h3>${t('固定期限内不提供常规提前赎回','Ordinary early redemption is unavailable')}</h3></div><p class="subtle">${t('已受理的 90 天、180 天及 365 天持仓按约定期限持有。提交申请不意味着可立即取回资金。','Accepted 90-, 180- and 365-day holdings run for their agreed term. Sending a request does not create a right to immediate withdrawal.')}</p></div><div class="card mt"><h3>${t('两种情形分别处理','Two separate circumstances')}</h3>${def(t('申购尚未受理','Before acceptance'),t('可申请取消，成功后释放预留','Cancellation may release reserved funds'))}${def(t('持仓已受理','After acceptance'),t('按例外退出条款单独处理','Exceptional exit terms apply separately'))}<p class="caption">${t('法律或协议允许的例外事项通过客服处理。收益调整及费用须在客户确认前说明；不承诺回购或二级市场买方。','Exceptions permitted by the agreement or applicable requirements are handled by support. Any adjustments and fees are explained before acceptance; no buyback or secondary buyer is promised.')}</p></div><div class="spacer"></div>${goBtn(t('联系客户服务','Contact support'),'support','secondary')}</main>`}
function redemptionPage(pid){const p=position(pid);if(!p)return holdingsPage();if(!['matured','redeem_failed'].includes(p.status))return maturityPage(p.id);return header(t('到期结算申请','Maturity settlement request'),'holding/'+p.id)+`<main class="page has-dock"><div class="card">${productLine(p.days)}<div class="spacer"></div>${def(t('本金','Principal'),money(p.principal)+' USDT')}${def(t('预计收益（非最终应付款）','Illustrative income, not final payable'),money(calc(p.principal,p.days))+' USDT')}${def(t('预计本息合计','Illustrative total'),`<strong>${money(p.principal+calc(p.principal,p.days))} USDT</strong>`)}${def(t('收款账户','Destination'),'GEXFI Wallet · USDT')}${def(t('额外赎回费用','Separate redemption fee'),t('以适用订单条款为准','Per accepted order terms'))}${def(t('当前产品管理费','Product management fee'),t('已反映，不重复扣除','Already reflected; not charged again'))}</div><div class="card mt"><h3>${t('结算后资金的去向','After settlement')}</h3><p class="subtle">${t('实际结算金额入账 GEXFI 钱包后，才可用于原有转账、兑换或卡服务。你不需要通过充值卡片才能取得赎回款。','The actual payable amount is credited to GEXFI Wallet before use in existing transfers, exchange or card services. Card funding is not required to receive your proceeds.')}</p><div class="mini-step"><span>${t('确认应付款','Confirm payable')}</span><span class="line"></span><span>${t('钱包入账','Wallet credit')}</span><span class="line"></span><span>${t('选择用途','Choose use')}</span></div></div><div class="spacer"></div>${notice(t('提交后显示“处理中”，不会立即增加可用余额。最终收益与净赎回额以结算单为准。','Submission creates a processing status; it does not immediately increase available funds. Final income and net proceeds are recorded on the settlement statement.'))}<p class="footnote">${t('本演示按每笔持仓全额结算；部分赎回未作为首期已确认功能开放。','This prototype settles a holding in full; partial redemption is not treated as an approved initial feature.')}</p></main>`+dock(t('提交模拟结算申请','Submit demo settlement request'),'redeem',`data-id="${p.id}"`)}
function timeline(rows){return`<ol class="timeline">${rows.map(([s,h,p])=>`<li class="${s}"><span class="dot"></span><div><h3>${h}</h3><p>${p}</p></div></li>`).join('')}</ol>`}
function settlementPage(pid){const p=position(pid);if(!p)return holdingsPage();if(p.status==='matured')return redemptionPage(pid);if(p.status==='active')return maturityPage(pid);const done=p.status==='redeemed',failed=p.status==='redeem_failed';return header(t('结算进度','Settlement progress'),'holding/'+p.id)+`<main class="page"><div class="result-hero"><div class="result-icon ${done?'':failed?'failed':'pending'}">${I(done?'check':failed?'info':'clock',28)}</div><h1>${done?t('已入账 GEXFI 钱包','Credited to GEXFI Wallet'):failed?t('结算需要处理','Settlement requires attention'):t('到期结算处理中','Maturity settlement in progress')}</h1><p class="subtle">${done?t('可用资金已更新；卡充值为下一笔独立交易。','Available funds have been updated. Card funding is a separate transaction.'):failed?t('本次未产生钱包入账，持仓及处理记录保留。','No wallet credit occurred. The holding and all processing records are retained.'):t('预计金额不等于已确认应付款，\n实际入账后才增加可用余额。','An estimate is not a confirmed payable.\nAvailable funds increase only after actual credit.').replace('\n','<br>')}</p><div class="large-number">${money(done?p.principal+p.actualIncome:p.principal+calc(p.principal,p.days))}<small>USDT</small></div><span class="caption">${done?t('实际净入账金额','Actual net credit'):t('目标收益情形下的示例金额','Illustrative amount at target')}</span></div><div class="card">${timeline([['done',t('持仓已到期','Term reached maturity'),fmtdate(p.end)],['done',t('申请已提交','Request submitted'),p.redemptionId||t('等待申请','Awaiting request')],[done?'done':'pending',t('核对并确认应付款','Reconcile and confirm payable'),done?t('结算单已生成','Statement generated'):failed?t('演示异常：执行失败，未入账','Demo exception: execution failed; no credit'):t('等待资产及账目核对','Awaiting reconciliation')],[done?'done':'',t('钱包入账','Wallet credit'),done?fmtdate(state.now):t('未完成，不计入可用余额','Not completed; not available funds')]])}</div>${done?`<div class="card mt">${def(t('本金','Principal'),money(p.principal)+' USDT')}${def(t('实际结算收益','Actual settled income'),money(p.actualIncome)+' USDT')}${def(t('额外扣项 · 演示','Other deductions · demo'),'0.00 USDT')}${def(t('入账参考','Credit reference'),p.creditId)}${def(t('结算后钱包可用余额','Available wallet funds'),money(available())+' USDT')}</div><div class="spacer"></div>${goBtn(t('前往卡充值','Continue to card funding'),'card-quote/'+p.id)}<div class="spacer-sm"></div>${goBtn(t('查看钱包衔接','Open wallet handoff'),'bridge/wallet','secondary')}<div class="spacer-sm"></div>${goBtn(t('再次申购 · 先核验资格','Reinvest · check eligibility'),'eligibility','secondary')}`:`<div class="spacer"></div>${failed?btn(t('重试结算申请','Retry settlement request'),'redeem','primary',`data-id="${p.id}"`):notice(t('可使用演示控制模拟“入账成功”或“执行失败”，查看余额变化。生产中仅接收真实服务端状态。','Demo controls can simulate credit or execution failure. Production accepts only authoritative server events.'))}<div class="spacer-sm"></div>${goBtn(t('联系客服','Contact support'),'support','secondary')}`}</main>`}
function cardQuotePage(pid){const p=position(pid);if(p&&p.status!=='redeemed')return settlementPage(p.id);if(!quote||quote.positionId!==pid){const amt=Math.min(1000,available()/SCALE);makeQuote(amt,pid)}return header(t('转入卡账户','Fund card account'),p?'settlement/'+p.id:'products')+`<main class="page has-dock"><div class="card-quote-visual"><div class="row"><span class="brand">GEXFI</span><span class="label">${t('卡充值衔接示意','CARD FUNDING HANDOFF')}</span></div><div><div class="label">${t('示例美元卡账户','Illustrative USD card account')}</div><strong>•••• 2048</strong></div><div class="row"><span class="label">USD ACCOUNT</span><span class="label">${t('非实际卡信息','NOT A REAL CARD')}</span></div></div><div class="card mt"><label class="input-label" for="card-amount">${t('从钱包支付','Pay from wallet')}</label><div class="amount-wrap"><input id="card-amount" type="number" inputmode="decimal" value="${quote.amount}" min="1" max="${available()/SCALE}" aria-label="${t('卡充值金额','Card funding amount')}"><span>USDT</span></div><div class="caption">${t('钱包可用','Wallet available')} ${money(available())} USDT</div><div id="card-quote-lines">${quoteLines()}</div></div><div class="spacer"></div>${notice(t('本页只演示“钱包 → 原有卡充值”资金衔接，不重做现有卡页面。实际币种、汇率、费用及限额必须取自原 Cards 报价接口。','This page illustrates the wallet-to-existing-card handoff, not a replacement card screen. Actual currencies, rates, fees and limits come from the existing Cards quote service.'))}<p class="footnote">${t('演示报价：1 USDT = 0.9985 USD、费用 1.00%、有效期 60 秒。均非已确认对外收费；报价过期须重新获取。','Demo only: 1 USDT = 0.9985 USD, 1.00% fee, valid for 60 seconds. These are not confirmed retail terms. An expired quote must be refreshed.')}</p></main>`+dock(t('确认模拟卡充值','Confirm demo card funding'),'fund-card','id="fund-card"')}
function makeQuote(a,pid){quote={id:'DEMO-Q-'+Date.now(),amount:Number(a),positionId:pid,rate:.9985,fee:.01,expires:Date.now()+60000};quote.usd=Math.round((quote.amount*(1-quote.fee)*quote.rate)*100)/100;quote.input=quote.amount}
function quoteLines(){return def(t('示例成交汇率','Illustrative execution rate'),'1 USDT = '+quote.rate+' USD')+def(t('示例服务费','Illustrative service fee'),num(quote.amount*quote.fee)+' USDT')+def(t('预计卡内入账','Expected card credit'),`<strong>${num(quote.usd)} USD</strong>`)+def(t('报价状态','Quote status'),`<span id="quote-status">${t('60 秒内有效','Valid for 60 seconds')}</span>`)}
function cardResultPage(cid){const c=state.cardOrders.find(c=>c.id===cid);if(!c)return productsPage();const done=c.status==='completed';return header(t('卡充值记录','Card funding record'),'activity')+`<main class="page"><div class="result-hero"><div class="result-icon ${done?'':c.status==='failed'?'failed':'pending'}">${I(done?'check':c.status==='failed'?'info':'clock',28)}</div><h1>${statusLabel(c.status)}</h1><p class="subtle">${done?t('模拟收到渠道成功结果，美元卡余额已更新。','A provider-success event has been simulated. The demo USD card balance is updated.'):c.status==='failed'?t('未完成卡充值，预留的 USDT 已原路释放。','Card funding was not completed; the USDT reservation was released.'):t('钱包金额已预留，等待卡渠道确认；卡余额尚未增加。','Wallet funds are reserved. The card balance does not increase until provider confirmation.')}</p><div class="large-number">${num(c.usd)}<small>USD</small></div></div><div class="card">${def(t('卡充值订单','Card order'),c.id)}${def(t('钱包支付金额','Wallet amount'),money(c.principal)+' USDT')}${def(t('示例汇率','Demo rate'),c.rate.toString())}${def(t('示例费用','Demo fee'),num(c.principal/SCALE*c.fee)+' USDT')}${def(t('卡入账状态','Card credit status'),done?t('已确认','Confirmed'):t('未入账','Not credited'))}${def(t('模拟卡余额','Demo card balance'),num(state.cardUSD)+' USD')}</div><div class="spacer"></div>${c.status==='processing'?notice(t('通过演示控制模拟渠道成功或失败。重复成功事件不会重复扣款或充值。','Simulate provider success or failure via Demo controls. Repeated success events do not duplicate debit or credit.')):''}<div class="spacer"></div>${goBtn(t('返回我的收益','Back to holdings'),'holdings','secondary')}</main>`}
function activityPage(){return header(t('收益宝交易记录','Income activity'),'holdings')+`<main class="page"><div class="tab-filters">${[['all',t('全部','All')],['purchase',t('购 U','Buy USDT')],['subscription',t('申购','Subscribe')],['redemption',t('赎回','Redeem')],['card',t('转卡','Card')]].map(([v,l])=>btn(l,'activity-filter',v===activityFilter?'active':'',`data-value="${v}"`)).join('')}</div><div class="card tight">${state.events.filter(e=>activityFilter==='all'||e.type===activityFilter).map(e=>`<button class="list-item" data-go="event/${e.id}"><div><span class="list-title">${esc(lang==='zh'?e.title[0]:e.title[1])}</span><p>${fmtdate(e.date)} · ${e.ref}</p></div><div class="right"><strong>${e.amount>0?'+':''}${money(e.amount)}</strong><small>USDT ${I('chevron',10)}</small></div></button>`).join('')||`<div class="empty">${I('file',32)}<h3>${t('还没有新交易记录','No new activity yet')}</h3><p>${t('模拟申购、取消、结算或转卡后，\n这里会保留对应记录。','Simulate a subscription, cancellation,\nsettlement or card funding to see records.').replace('\n','<br>')}</p></div>`}</div><p class="footnote">${t('这里仅列收益模块相关活动。现有钱包、汇兑及卡交易记录页保持不变。','This view contains Income-related activity only. Existing wallet, FX and card histories are unchanged.')}</p></main>`}
function eventPage(eid){const e=state.events.find(e=>e.id===eid);if(!e)return activityPage();return header(t('交易详情','Activity details'),'activity')+`<main class="page"><div class="card">${def(t('事件','Event'),esc(lang==='zh'?e.title[0]:e.title[1]))}${def(t('金额变化','Movement'),money(e.amount)+' USDT')}${def(t('业务编号','Reference'),e.ref)}${def(t('记录编号','Record ID'),e.id)}${def(t('业务日期','Business date'),fmtdate(e.date))}${def(t('演示操作时间','Demo action time'),e.at)}</div><div class="spacer"></div>${notice(t('记录为本地演示操作轨迹，不是实际银行或链上凭据。资金预留、持仓建立与到账分别记账。','This is a local demo audit trail, not a bank or on-chain proof. Reservations, accepted holdings and actual credits are recorded separately.'))}</main>`}
function memoPage(section){const labels=D.memo.labels[lang],sections=D.memo.sections[lang];if(section){const s=sections.find(x=>x.id===section);if(!s)return memoPage();return header(s.title,'memo')+`<article class="memo-body"><div class="eyebrow">${s.number} / GEX USDT INCOME</div><h1 style="font-size:23px;line-height:1.4">${s.title}</h1><p>${s.intro}</p>${s.body}<div class="spacer"></div>${goBtn(t('返回文件目录','Back to contents'),'memo','secondary')}<p class="caption">v1.0 · 2026-10-08</p></article>`}return header(t('投资说明书','Investment Memorandum'),consent.memo||route.includes('memo')?'products':'products')+`<main class="page"><div class="eyebrow">PRODUCT DOCUMENTS</div><h1>${labels.document}</h1><div class="subtle">GEX USDT Income</div><p class="caption">${labels.scope}</p><div class="row" style="margin:20px 0"><span class="pill">v1.0 · 2026-10-08</span>${btn(I('download',15)+' PDF','download-pdf','link')}</div>${notice(labels.risk)}<div class="memo-index">${sections.map(s=>`<button class="list-item" data-go="memo/${s.id}"><div class="row start"><span class="caption">${s.number}</span><span class="list-title" style="margin:0">${s.title}</span></div>${I('chevron',14)}</button>`).join('')}</div><p class="caption" style="margin-top:15px">${labels.status}</p><div class="button-pair">${btn(t('下载中文 PDF','Chinese PDF'),'download-pdf','secondary','data-lang="zh"')}${btn(t('下载英文 PDF','English PDF'),'download-pdf','secondary','data-lang="en"')}</div><div class="spacer"></div>${goBtn(t('返回申购确认','Back to subscription review'),'review','secondary')}</main>`}
function rulesPage(){return header(t('产品规则与风险','Rules & risks'),'products')+`<main class="page"><div class="card"><h3>${t('已确认的产品口径','Confirmed product basis')}</h3>${def('90 '+t('天','days'),'3.80% '+t('目标年化','net target p.a.'))}${def('180 '+t('天','days'),'4.50% '+t('目标年化','net target p.a.'))}${def('365 '+t('天','days'),'5.00% '+t('目标年化','net target p.a.'))}${def(t('管理费','Management fee'),t('0.50%/年已反映于目标收益','0.50% p.a. reflected in target'))}${def(t('计算','Calculation'),'ACT/365 · '+t('单利','simple interest'))}${def(t('申购资金','Funding'),t('已结算合资格 GEXFI 购U','Eligible settled GEXFI purchases'))}${def(t('赎回与续投','Exit & renewal'),t('到期结算，不自动续投','Maturity settlement; no auto-renewal'))}</div><div class="card mt"><h3>${t('理解三类收益数值','Understand three income figures')}</h3><p class="subtle">${t('预计收益：按目标利率的试算及计提展示。\n已确认收益：经过实际结算核对的应付款。\n已入账收益：已完成钱包入账的金额。','Estimated income: illustrations using the target rate.\nConfirmed income: payable income after actual reconciliation.\nCredited income: completed wallet credits.').replaceAll('\n','<br><br>')}</p></div><div class="spacer"></div>${notice(t('目标收益不保证，本金存在风险。固定期限不适合作为应急或短期消费资金。','Target returns are not guaranteed and capital is at risk. Fixed-term holdings are not emergency or short-term spending funds.'),'warn')}<div class="spacer"></div>${goBtn(t('阅读全文与风险披露','Read the full memorandum'),'memo')}</main>`}
function bridgePage(type){const m={buy:[t('购买 USDT','Buy USDT'),t('现有汇兑页面','Existing Exchange'),t('完成原有购U及到账审核后，由服务端刷新可申购金额。收益宝不另建入金通道。','After the existing purchase and settlement process, the server refreshes eligible funds. Income does not add a new deposit rail.')],kyc:[t('账户认证','Account verification'),t('现有认证中心','Existing verification centre'),t('继续使用当前账户与认证状态，不重复注册或单独创建客户资料。','Reuse the existing account and verification status, without a duplicate registration or client record.')],card:[t('卡账户','Card account'),t('现有卡页面','Existing Cards'),t('底部“银联卡”入口不改名、不换页面。收益宝到卡的资金请求交给现有卡充值流程。','Do not rename or replace the existing UnionPay tab. Income hands funding requests to the existing card flow.')],wallet:[t('钱包','Wallet'),t('现有资产页面','Existing wallet'),t('钱包只接收实际结算完成的入账。收益持仓和预留不重复计入可用余额。','Wallet receives completed settlement credits only. Holdings and reservations are not double-counted as available funds.')]}[type]||[type,t('现有服务','Existing service'),''];return header(m[0],'products')+`<main class="page"><div class="card empty">${I(type==='card'?'card':type==='buy'?'exchange':type==='kyc'?'shield':'wallet',36)}<h3>${m[1]}</h3><p>${m[2]}</p>${pill(t('保留原页面 · 仅接口衔接','Original page retained · handoff only'))}</div><div class="card mt"><h3>${t('集成边界','Integration boundary')}</h3><p class="subtle">${t('你提供的是现有页面截图和官网代码包，没有当前 H5 工程。本演示不虚构这些页面的代码或真实地址。IT 将这一入口绑定现有 router / service。','The supplied materials include screenshots and the website package, not the live H5 source. This prototype does not invent existing page code or routes. IT binds this handoff to the current router and service.')}</p></div><div class="spacer"></div>${goBtn(t('返回收益宝','Back to Income'),'products','secondary')}</main>`}
function supportPage(){return header(t('帮助与联系','Help & contact'),'products')+`<main class="page"><div class="card"><div class="row start"><span class="list-icon">${I('support',22)}</span><div><h3>GEXFI</h3><div class="caption">${t('账户与收益产品支持','Account & Income product support')}</div></div></div><p class="subtle">${t('请提供订单编号与问题描述。不要发送密码、私钥或完整卡片凭据。','Include your order reference and issue description. Do not send passwords, private keys or full card credentials.')}</p><a class="primary" href="mailto:info@gexfi.com">info@gexfi.com</a></div><div class="card mt tight"><button class="list-item" data-go="rules"><span>${t('收益与到期规则','Income & maturity rules')}</span>${I('chevron',14)}</button><button class="list-item" data-go="eligibility"><span>${t('为什么余额不能全部申购？','Why is some balance ineligible?')}</span>${I('chevron',14)}</button><button class="list-item" data-go="memo"><span>Investment Memorandum</span>${I('chevron',14)}</button></div></main>`}
function render(){route=(location.hash.replace(/^#\/?/,'')||'home');const parts=route.split('/'), r=parts[0],v=parts[1];let html='';switch(r){case'home':case'me':case'more':case'exchange':html=originalPage(r);break;case'buy':html=buyPage(v||chosen);break;case'checkout':html=checkoutPage(v);break;case'buy-order':html=buyOrderPage(v);break;case'payments':html=paymentsPage();break;case'payment-unavailable':html=paymentUnavailablePage();break;case'products':html=productsPage();break;case'product':html=productPage(pBy(v).days);break;case'eligibility':html=eligibilityPage();break;case'subscribe':html=subscribePage(pBy(v).days);break;case'review':html=reviewPage();break;case'order':html=orderPage(v);break;case'holdings':html=holdingsPage();break;case'holding':html=holdingPage(v);break;case'income':html=dailyPage(v);break;case'receipt':html=receiptPage(v);break;case'chain':html=chainPage(v);break;case'maturity':html=maturityPage(v);break;case'early':html=earlyPage(v);break;case'redeem':html=redemptionPage(v);break;case'settlement':html=settlementPage(v);break;case'card-quote':html=cardQuotePage(v);break;case'card-result':html=cardResultPage(v);break;case'activity':html=activityPage();break;case'event':html=eventPage(v);break;case'memo':html=memoPage(v);break;case'rules':html=rulesPage();break;case'bridge':html=bridgePage(v);break;case'support':html=supportPage();break;case'export':downloadDaily(position(v));go('income/'+v);return;default:html=productsPage();}
const screen=document.getElementById('screen');screen.innerHTML=(['home','me','more','exchange'].includes(r)?'':demoStrip())+html;screen.scrollTop=0;document.getElementById('overlays').innerHTML='';document.documentElement.lang=lang==='zh'?'zh-CN':'en';renderBench();save();}
function go(to){closeSheet();if(location.hash==='#/'+to)render();else location.hash='/'+to}
const pageNav=()=>[['01',t('三个原页入口','Three original-page entries'),null],['',t('首页 · 新增产品卡','Home · product entry'),'home'],['',t('我的资产 · 收益持仓','My assets · holdings entry'),'me'],['',t('更多功能 · 收益中心','More · Income centre'),'more'],['02',t('发现与申购','Explore & subscribe'),null],['',t('收益中心 / 三档产品','Income centre / products'),'products'],['',t('产品详情 / 收益试算','Product / calculator'),'product/180'],['',t('资格 / 可申购资金','Eligibility / funding'),'eligibility'],['',t('输入申购金额','Subscription amount'),'subscribe/180'],['',t('条款 / 确认申购','Terms / confirmation'),'review'],['',t('法币购U / 付款方式','Fiat purchase / payment method'),'buy/180'],['',t('购U与付款记录','Purchase / payment records'),'payments'],['03',t('持仓与记录','Holdings & records'),null],['',t('我的收益资产','My holdings'),'holdings'],['',t('持仓详情 / 收益曲线','Holding / income chart'),'holding'],['',t('每日收益明细','Daily accrual'),'income'],['',t('申购确认凭证','Confirmation receipt'),'receipt'],['',t('链上记录状态','On-chain status'),'chain'],['04',t('到期与消费','Maturity & spending'),null],['',t('到期处理 / 不自动续投','Maturity instructions'),'maturity'],['',t('到期结算申请','Maturity settlement'),'redeem'],['',t('结算处理中 / 成功 / 失败','Settlement states'),'settlement'],['',t('钱包 → 原卡充值','Wallet → existing Cards'),'card-quote'],['',t('交易记录 / 详情','Activity / details'),'activity'],['05',t('文件与异常','Documents & exceptions'),null],['',t('双语 Memo / PDF','Bilingual Memo / PDF'),'memo'],['',t('产品规则与风险','Product rules & risk'),'rules'],['',t('提前退出 / 取消区别','Early exit / cancellation'),'early'],['',t('原页面衔接边界','Existing-page handoff'),'bridge/card']];
function navTarget(v){if(['holding','income','receipt','chain','maturity','early'].includes(v))return v+'/'+(state.positions.find(p=>p.status==='active')?.id||state.positions[0]?.id||'');if(['redeem','settlement'].includes(v))return v+'/'+(state.positions.find(p=>['matured','redeeming','redeem_failed','redeemed'].includes(p.status))?.id||state.positions[0]?.id||'');if(v==='card-quote')return state.positions.some(p=>p.status==='redeemed')?'card-quote/'+state.positions.find(p=>p.status==='redeemed').id:'card-quote/';return v}
function renderBench(){document.getElementById('rail').innerHTML=`<div class="rail-brand">GEXFI <small>H5 / INCOME</small></div><h1>${t('原系统不动，\n收益模块新增。','Existing H5 retained.\nIncome added.').replace('\n','<br>')}</h1><p>${t('深色统一 + 法币购U付款 + 原有完整收益链路。\n选择左侧页面，或直接在手机内操作。','Dark visual continuity, fiat purchase checkout and the complete Income journey. Select a screen or interact in the preview.').replace('\n','<br>')}</p>${pageNav().map(([n,title,to])=>to?`<button data-go="${navTarget(to)}" class="${route===navTarget(to)?'selected':''}"><span class="num">${I(to==='home'?'home':to==='memo'?'file':to==='holdings'?'wallet':'chevron',13)}</span>${title}</button>`:`<div class="rail-label">${n} &nbsp;${title}</div>`).join('')}<div class="spacer"></div><p>${t('DEMO · 所有金额及状态为本地模拟。\n不发送资金或真实申购请求。','DEMO · Local balances and states only. No real funds or subscription requests.')}</p>`;
const original=['home','me','more','exchange'].includes(route);let h=original?t('只增加入口，不重排旧页。','Add entries. Keep the old layout.'):t('每一步都有独立状态。','A distinct state at every step.');let note=original?t('手机内深色区域直接使用你提供的原H5截图。只有“USDT收益宝 / 收益资产 / 收益中心”卡片是新增可操作元素；截图中的余额不参与演示账务。','The dark original-page sections are your actual screenshots. Only the new Income entries are interactive; screenshot balances are not demo ledger data.'):t('新页面统一沿用现有 H5 的深色背景、深蓝面板与蓝色操作按钮。新增法币购U与支付进度；原有账户、汇兑和卡页面不重做。','The existing dark background, navy panels and blue action buttons continue throughout Income and checkout. Existing account, exchange and card pages are retained.');document.getElementById('notes').innerHTML=`<div class="eyebrow">INCREMENTAL INTEGRATION / V2</div><h2>${h}</h2><p>${note}</p><div class="divider"></div><div class="metric"><strong>${t('已确认的产品参数','Approved product parameters')}</strong><span>90${t('天','d')} 3.80% · 180${t('天','d')} 4.50% · 365${t('天','d')} 5.00%<br>${t('目标年化已反映管理费。','Net targets reflect the management fee.')}<br>ACT/365 · ${t('单利','Simple interest')}</span></div><div class="metric"><strong>${t('申购边界','Funding boundary')}</strong><span>${t('仅已入账合资格GEXFI购U资金。外部转入、待入账和预留不可申购。','Only settled eligible GEXFI-purchased USDT. External, unsettled and reserved amounts are excluded.')}</span></div><div class="metric"><strong>${t('闭环演示','End-to-end demo')}</strong><span>${t('确认申购 → 演示控制“受理” → 持仓。\n到期订单 → 结算申请 → 模拟入账 → 卡充值。','Submit → simulate acceptance → holding.\nMature → request settlement → simulate credit → card funding.').replace('\n','<br>')}</span></div><div class="divider"></div><p>${t('当前演示业务日期','Demo business date')}<br><strong>${state.now}</strong></p><p>${t('最低100U、2个工作日结算、卡费率均为演示参数。真实值必须由既有系统提供。','The 100U minimum, two-business-day settlement and card pricing are demo parameters, not new product commitments.')}</p>`;document.getElementById('stage-name').textContent=t('GEXFI · 收益宝增量预览','GEXFI · Income integration');document.getElementById('stage-caption').textContent=original?t('真实旧页截图 + 新增入口定位；原有底部菜单不增加“收益”Tab。','Actual screenshot + new entry placement. No extra Income bottom tab.'):t('可点击原型 · 演示操作保存在当前浏览器，可从演示控制重置。','Interactive prototype · local demo state persists; reset via Demo controls.');}
function toast(text){let old=document.querySelector('.toast');if(old)old.remove();const d=document.createElement('div');d.className='toast';d.setAttribute('role','status');d.textContent=text;document.getElementById('overlays').appendChild(d);clearTimeout(toastTimer);toastTimer=setTimeout(()=>d.remove(),4200)}
function sheet(title,body){document.getElementById('overlays').innerHTML=`<div class="modal-backdrop" data-act="backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="row"><h2>${title}</h2>${btn(I('close'),'close','icon-btn','aria-label="Close"')}</div>${body}</section></div>`}
function closeSheet(){document.getElementById('overlays').innerHTML=''}
function openDemo(){const o=state.orders.find(o=>o.id===routeId()&&o.status==='pending')||state.orders.find(o=>o.status==='pending');const p=position(routeId());const c=state.cardOrders.find(c=>c.id===routeId()&&c.status==='processing')||state.cardOrders.find(c=>c.status==='processing');sheet(t('演示控制','Demo controls'),`<p>${t('这些操作只改变当前浏览器的模拟数据，不出现在正式客户页面。申购、结算、卡充值均未接通真实服务。','These controls change local demo data only and are not production customer controls. No live subscription, settlement or card service is connected.')}</p>${o?`${btn(t('模拟受理申购','Simulate subscription acceptance'),'accept','demo-control',`data-id="${o.id}"`)}${btn(t('模拟申购未受理 · 释放预留','Simulate rejection · release reservation'),'reject','demo-control',`data-id="${o.id}"`)}`:''}${p&&p.status==='active'?btn(t('将当前持仓推进至到期日','Advance this holding to maturity'),'advance','demo-control',`data-id="${p.id}"`):''}${p&&p.status==='redeeming'?`<label class="input-label" for="actual-income">${t('实际结算收益 · 可不同于目标（演示）','Actual settlement income · may differ from target (demo)')}</label><input class="input-basic" id="actual-income" type="number" step="0.01" value="${(calc(p.principal,p.days)/SCALE).toFixed(2)}">${btn(t('模拟钱包成功入账','Simulate wallet credit'),'settle','demo-control',`data-id="${p.id}"`)}${btn(t('模拟结算执行失败','Simulate settlement execution failure'),'settle-fail','demo-control',`data-id="${p.id}"`)}`:''}${c?`${btn(t('模拟渠道确认卡充值成功','Simulate provider funding success'),'card-success','demo-control',`data-id="${c.id}"`)}${btn(t('模拟渠道失败 · 释放钱包预留','Simulate provider failure · release reservation'),'card-fail','demo-control',`data-id="${c.id}"`)}`:''}${quote&&route.startsWith('card-quote')?btn(t('使本次卡报价立即过期','Expire this card quote now'),'expire-quote','demo-control'):''}<div class="spacer"></div>${btn(t('重置：已有持仓 + 到期订单','Reset: existing holdings + mature order'),'reset','demo-control','data-mode="holdings"')}${btn(t('重置：首次申购客户','Reset: first-time subscriber'),'reset','demo-control','data-mode="empty"')}${btn(t('重置：仅有外部USDT，无购U资格','Reset: external USDT only'),'reset','demo-control','data-mode="external"')}${btn(t('切换认证状态','Toggle verification status'),'toggle-kyc','demo-control')}${btn(t('模拟待入账购U资金完成结算','Simulate pending GEXFI purchase settlement'),'purchase-settle','demo-control')}<p>${t('账户可用','Wallet available')}: ${money(available())} USDT<br>${t('其中可申购','Eligible')}: ${money(state.funds.eligible)} USDT<br>${t('预留资金','Reserved')}: ${money(state.funds.reserved)} USDT</p>${goBtn(t('返回原H5入口预览','Original H5 entry preview'),'home','secondary')}`)}
function submit(){const err=amountError(amount);if(err){toast(err);return}if(!consent.memo||!consent.risk){toast(t('请先确认已阅读相关文件与风险。','Acknowledge the documents and risks first.'));return}const principal=micro(amount),o={id:id('SUB'),days:chosen,principal,status:'pending',created:state.now,memo:'1.0',sourcePurchaseId:selectedPurchaseId||null,rate:pBy(chosen).rate};state.orders.unshift(o);state.funds.eligible-=principal;state.funds.reserved+=principal;event('subscription',['申购提交 · 资金预留','Subscription submitted · funds reserved'],-principal,o.id);consent={memo:false,risk:false};go('order/'+o.id)}
function resolveOrder(oid,status){const o=state.orders.find(x=>x.id===oid);if(!o||o.status!=='pending'){toast(t('订单已处理，未重复执行。','Already processed; no duplicate action.'));return}o.status=status;state.funds.reserved-=o.principal;if(status==='accepted'){const pid=id('IN');o.positionId=pid;state.positions.unshift({id:pid,days:o.days,principal:o.principal,start:state.now,end:dayAdd(state.now,o.days),status:'active',rate:o.rate,memo:o.memo,autoRenew:false});event('subscription',['申购受理 · 已建立持仓','Accepted · holding created'],0,o.id)}else{state.funds.eligible+=o.principal;event('subscription',status==='cancelled'?['申购已取消 · 预留释放','Cancelled · reservation released']:['申购未受理 · 预留释放','Rejected · reservation released'],o.principal,o.id)}save();go('order/'+o.id)}
function requestRedeem(pid){const p=position(pid);if(!p||!['matured','redeem_failed'].includes(p.status)){toast(t('持仓尚未到期或已经处理。','Not matured or already processing.'));return}p.status='redeeming';p.redemptionId=p.redemptionId||id('RED');p.expectedBy=businessAdd(state.now,2);event('redemption',['到期结算申请 · 尚未入账','Maturity requested · not yet credited'],0,p.redemptionId);go('settlement/'+p.id)}
function settle(pid,fail){const p=position(pid);if(!p||p.status!=='redeeming'){toast(t('本次结算已处理，未重复入账。','Settlement already processed; no duplicate credit.'));return}if(fail){p.status='redeem_failed';event('redemption',['结算失败 · 未产生入账','Settlement failed · no credit'],0,p.redemptionId)}else{const input=document.getElementById('actual-income');const actual=input?Number(input.value):calc(p.principal,p.days)/SCALE;if(!Number.isFinite(actual)||micro(actual)<-p.principal){toast(t('净结算金额不能为负。','Net settlement cannot be negative.'));return}p.actualIncome=micro(actual);p.status='redeemed';p.creditId=id('WAL');state.funds.returned+=p.principal+p.actualIncome;event('redemption',['到期结算完成 · 钱包已入账','Maturity settled · wallet credited'],p.principal+p.actualIncome,p.creditId)}save();go('settlement/'+p.id)}
function withdrawBuckets(principal){let rem=principal;const used={returned:0,external:0,eligible:0};for(const k of ['returned','external','eligible']){let n=Math.min(state.funds[k],rem);state.funds[k]-=n;used[k]=n;rem-=n;}if(rem!==0)throw Error('INSUFFICIENT_FUNDS');state.funds.reserved+=principal;return used}
function fundCard(){if(!quote||quote.expires<Date.now()){toast(t('报价已过期，请重新获取。','Quote expired. Refresh to continue.'));sheet(t('报价已过期','Quote expired'),`<p>${t('金额未扣除。重新获取后再次确认汇率、费用与卡内到账金额。','No funds were debited. Refresh and re-confirm the rate, fee and card credit.')}</p>${btn(t('重新获取报价','Refresh quote'),'refresh-quote')}`);return}if(!Number.isFinite(quote.amount)||quote.amount<=0||micro(quote.amount)>available()){toast(t('钱包可用金额不足或输入不正确。','Invalid amount or insufficient wallet funds.'));return}const c={id:id('CARD'),status:'processing',principal:micro(quote.amount),usd:quote.usd,rate:quote.rate,fee:quote.fee,quoteId:quote.id,expires:quote.expires,used:withdrawBuckets(micro(quote.amount))};state.cardOrders.unshift(c);event('card',['卡充值提交 · 钱包资金预留','Card funding submitted · wallet reserved'],-c.principal,c.id);quote=null;go('card-result/'+c.id)}
function resolveCard(cid,fail){const c=state.cardOrders.find(x=>x.id===cid);if(!c||c.status!=='processing'){toast(t('渠道结果已处理，未重复扣款或充值。','Provider result processed; no duplicate debit or credit.'));return}state.funds.reserved-=c.principal;c.status=fail?'failed':'completed';if(fail){for(const k of Object.keys(c.used))state.funds[k]+=c.used[k];event('card',['卡充值未完成 · 预留已释放','Card funding failed · reservation released'],c.principal,c.id)}else{state.cardUSD=Math.round((state.cardUSD+c.usd)*100)/100;event('card',['渠道确认 · 美元卡已入账','Provider confirmed · USD card credited'],0,c.id)}save();go('card-result/'+c.id)}
function download(text,name,type='text/plain;charset=utf-8'){const blob=text instanceof Blob?text:new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function downloadPDF(l){const f=D.pdfs[l||lang];if(f.startsWith('data:')){const s=atob(f.split(',')[1]);const a=new Uint8Array(s.length);for(let i=0;i<s.length;i++)a[i]=s.charCodeAt(i);download(new Blob([a],{type:'application/pdf'}),'GEX_USDT_Income_Investment_Memorandum_'+(l||lang).toUpperCase()+'_v1.0.pdf')}else{const a=document.createElement('a');a.href=f;a.download=f.split('/').pop();a.click()}}
function downloadDaily(p){if(!p)return;let rows=['\uFEFFDEMO ONLY - NOT ACTUAL PAYMENTS','Date,Product,Principal_USDT,Target_p_a,Estimated_daily_USDT,Status'];for(let d=1;d<=elapsed(p);d++)rows.push([dayAdd(p.start,d),'USDT Income '+p.days,p.principal/SCALE,p.rate,(p.principal/SCALE*p.rate/365).toFixed(6),'ESTIMATED_NOT_PAID'].join(','));download(rows.join('\r\n'),p.id+'-estimated-income-DEMO.csv','text/csv;charset=utf-8')}
function inputUpdate(e){if(e.target.id==='trial-amount'){amount=Math.max(0,Math.min(50000,Number(e.target.value)||0));document.getElementById('trial-rows').innerHTML=trialRows(chosen,amount)}else if(e.target.id==='subscribe-amount'){amount=Number(e.target.value);document.getElementById('subscription-rows').innerHTML=trialRows(chosen,Math.max(0,amount||0));const err=amountError(amount);document.getElementById('amount-error').textContent=err;document.getElementById('review-button').disabled=!!err}else if(e.target.id==='card-amount'){makeQuote(Number(e.target.value),routeId());document.getElementById('card-quote-lines').innerHTML=quoteLines()}else if(e.target.id==='consent-memo'||e.target.id==='consent-risk'){consent[e.target.id==='consent-memo'?'memo':'risk']=e.target.checked;document.getElementById('confirm-subscribe').disabled=!(consent.memo&&consent.risk)}}
document.addEventListener('input',inputUpdate);document.addEventListener('change',inputUpdate);
document.addEventListener('click',e=>{const b=e.target.closest('[data-go],[data-act]');if(!b||b.disabled)return;if(b.hasAttribute('data-go')){e.preventDefault();go(b.dataset.go);return}const a=b.dataset.act,v=b.dataset.value,pid=b.dataset.id;e.preventDefault();switch(a){case'backdrop':if(e.target===b)closeSheet();break;case'close':closeSheet();break;case'demo':openDemo();break;case'language':lang=lang==='zh'?'en':'zh';localStorageSafe('set','gxi-lang',lang);render();break;case'trial':amount=Number(v);render();break;case'amount':amount=v==='max'?Math.min(state.funds.eligible/SCALE,50000):Number(v);render();break;case'start-subscribe':chosen=Number(b.dataset.days);if(!state.verified){go('eligibility');break}go('subscribe/'+chosen);break;case'review':if(amountError(amount)){toast(amountError(amount));break}go('review');break;case'submit':submit();break;case'cancel-order':sheet(t('取消未受理申购？','Cancel this pending instruction?'),`<p>${t('仅在尚未受理时取消。取消成功后，本次预留金额恢复为可申购资金。','Cancellation is available only before acceptance. Successful cancellation releases the reserved amount.')}</p>${btn(t('确认取消','Confirm cancellation'),'cancel-confirm','primary',`data-id="${pid}"`)}<div class="spacer-sm"></div>${btn(t('继续等待受理','Keep waiting'),'close','secondary')}`);break;case'cancel-confirm':resolveOrder(pid,'cancelled');break;case'accept':resolveOrder(pid,'accepted');break;case'reject':resolveOrder(pid,'rejected');break;case'hold-filter':holdingsFilter=v;render();break;case'activity-filter':activityFilter=v;render();break;case'range':{const sc=document.getElementById('screen').scrollTop;range=Number(v);render();document.getElementById('screen').scrollTop=sc;break}case'download-pdf':downloadPDF(b.dataset.lang);break;case'download-receipt':{const p=position(pid);download(JSON.stringify({demo:true,...p,disclaimer:'DEMO ONLY. Not an accepted contract or on-chain proof.'},null,2),p.id+'-DEMO-confirmation.json','application/json');break}case'advance':{const p=position(pid);state.now=p.end;for(const x of state.positions)if(x.status==='active'&&x.end<=state.now)x.status='matured';save();go('holding/'+p.id);break}case'redeem':requestRedeem(pid);break;case'settle':settle(pid,false);break;case'settle-fail':settle(pid,true);break;case'fund-card':fundCard();break;case'card-success':resolveCard(pid,false);break;case'card-fail':resolveCard(pid,true);break;case'expire-quote':if(quote)quote.expires=Date.now()-1;closeSheet();toast(t('本次报价已设为过期。','Quote is now expired.'));break;case'refresh-quote':if(quote)makeQuote(quote.amount,quote.positionId);render();break;case'reset':state=seed(b.dataset.mode!=='holdings');if(b.dataset.mode==='external')state.funds.eligible=0;amount=1000;quote=null;consent={memo:false,risk:false};save();go('products');break;case'toggle-kyc':state.verified=!state.verified;save();go('eligibility');break;case'purchase-settle':state.funds.eligible+=state.funds.pending;state.funds.pending=0;save();go('eligibility');break;}});
window.addEventListener('hashchange',render);window.addEventListener('storage',e=>{if(e.key===K){state=load();render();toast(t('演示状态已同步。','Demo state synchronized.'))}});
setInterval(()=>{const el=document.getElementById('quote-status');if(el&&quote){const n=Math.max(0,Math.ceil((quote.expires-Date.now())/1000));el.textContent=n?t(`剩余 ${n} 秒`,`${n}s remaining`):t('已过期，请重新获取','Expired; refresh required');el.classList.toggle('danger',n===0)}},1000);
/*PAYMENT_MODULE*/
state=load();
window.App={go,openDemo};window.GXIDemoTest={getState:()=>JSON.parse(JSON.stringify(state)),reset:(mode='holdings')=>{state=seed(mode!=='holdings');if(mode==='external')state.funds.eligible=0;save();render()},setAmount:(v,d)=>{amount=v;chosen=d;consent={memo:true,risk:true}},submit,resolveOrder,requestRedeem,settle,resolveCard,advance:(pid)=>{const p=position(pid);state.now=p.end;for(const q of state.positions)if(q.status==='active'&&q.end<=state.now)q.status='matured';save();render()},setLanguage:l=>{lang=l;render()},productCalculation:(v,d)=>calc(micro(v),d)/SCALE,makeQuote,expireQuote:()=>{if(quote)quote.expires=Date.now()-1},fundCard,amountError,available:()=>available()/SCALE};render();
})();
